<?php require __DIR__.'/includes/bootstrap.php';requireLogin();$id=(int)($_GET['event_id']??0);$statement=$pdo->prepare('SELECT * FROM events WHERE event_id=?');$statement->execute([$id]);$event=$statement->fetch();if(!$event||!isEventOwnerOrAdmin($event)){http_response_code(403);exit('You cannot view this attendee list.');}$statement=$pdo->prepare('SELECT b.*,u.name,u.email FROM bookings b JOIN users u ON u.user_id=b.user_id WHERE b.event_id=? ORDER BY b.created_at');$statement->execute([$id]);$attendees=$statement->fetchAll();$statement=$pdo->prepare('SELECT w.*,u.name FROM waiting_list w JOIN users u ON u.user_id=w.user_id WHERE w.event_id=? ORDER BY w.joined_at,w.entry_id');$statement->execute([$id]);$waiting=$statement->fetchAll();$pageTitle='Attendees';require __DIR__.'/includes/header.php'; ?>
<h1>Attendees: <?=e($event['title'])?></h1><p><a href="event.php?id=<?=$id?>">View event</a></p><h2>Confirmed attendees</h2><?php if(!$attendees):?><p class="notice">No confirmed bookings.</p><?php else:?><table><thead><tr><th>Name</th><th>Email</th><th>Booking status</th><th class="no-print">Check-in</th></tr></thead><tbody><?php foreach($attendees as $person):?><tr><td><?=e($person['name'])?></td><td><?=e($person['email'])?></td><td><?=$person['checked_in']?'Checked in':'Not checked in'?></td><td class="no-print"><?php if(!$person['checked_in']):?><form method="post" action="checkin.php"><?= csrfField() ?><input type="hidden" name="booking_id" value="<?= (int)$person['booking_id']?>"><input type="hidden" name="event_id" value="<?=$id?>"><button>Mark checked in</button></form><?php endif?></td></tr><?php endforeach?></tbody></table><?php endif?><h2>Waiting list (FIFO)</h2><?php if(!$waiting):?><p class="notice">Nobody is waiting.</p><?php else:?><ol><?php foreach($waiting as $person):?><li><?=e($person['name'])?> — joined <?=e(date('j M Y, H:i',strtotime($person['joined_at'])))?></li><?php endforeach?></ol><?php endif;require __DIR__.'/includes/footer.php';
